import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_native_splash/flutter_native_splash.dart';

import '../domain/l10n.dart';
import 'loading_bar.dart' show SweepPainter;
import 'theme.dart';

/// The launch screen's hand-off into the app. The native splash (generated by
/// flutter_native_splash from pubspec.yaml: the AURA mark on navy, "AURA GYM"
/// at the bottom) goes on the app's first frame; this layer, drawn the same,
/// takes its place without a seam and adds a slim gold loading line under the
/// mark (the app's own loading sweep), so the start never looks frozen. After a
/// short beat it fades into the app (~1 s in all). Skipped with reduced motion.
class SplashReveal extends StatefulWidget {
  const SplashReveal({super.key, required this.child});
  final Widget child;

  /// The mark, as the native splash shows it (assets/splash/logo.png: 1024 px at
  /// 4x = 256 logical px, the mark itself in its middle).
  static const logo = AssetImage('assets/splash/logo.png');
  static const branding = AssetImage('assets/splash/branding.png');
  static const _logoSize = 256.0;

  /// The loading line: under the mark, as wide as the mark itself.
  static const _barWidth = 132.0;
  static const _barGap = 84.0; // from the screen's centre

  /// How long the loading line runs before the app shows, and the fade into it.
  static const hold = Duration(milliseconds: 650);
  static const exit = Duration(milliseconds: 350);

  /// Keeps the native splash on screen until [SplashReveal] can draw.
  static void preserve(WidgetsBinding binding) => FlutterNativeSplash.preserve(widgetsBinding: binding);

  @override
  State<SplashReveal> createState() => _SplashRevealState();
}

class _SplashRevealState extends State<SplashReveal> with TickerProviderStateMixin {
  late final AnimationController _sweep =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 1100));
  late final AnimationController _exit = AnimationController(vsync: this, duration: SplashReveal.exit);
  bool _started = false;
  bool _done = false;
  Timer? _hold;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_started || _done) return;
    _started = true;
    // The mark is decoded first so the hand-off has no blank frame; never waited on for long.
    Future.any([
      Future.wait([precacheImage(SplashReveal.logo, context), precacheImage(SplashReveal.branding, context)]),
      Future<void>.delayed(const Duration(milliseconds: 150)),
    ]).whenComplete(() {
      if (!mounted) return;
      FlutterNativeSplash.remove();
      final reduce = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
      if (reduce) return setState(() => _done = true);
      _sweep.repeat();
      _hold = Timer(SplashReveal.hold, () {
        if (!mounted) return;
        _exit.forward().whenComplete(() {
          if (!mounted) return;
          _sweep.stop(); // no frames once the layer is gone
          setState(() => _done = true);
        });
      });
    });
  }

  @override
  void dispose() {
    _hold?.cancel();
    _sweep.dispose();
    _exit.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // The app keeps its place in the tree when the layer goes, so it is never rebuilt from scratch.
    if (_done) {
      return Directionality(
          textDirection: TextDirection.ltr, child: Stack(fit: StackFit.expand, children: [widget.child]));
    }
    final out = CurvedAnimation(parent: _exit, curve: Curves.easeOut);
    final fade = Tween(begin: 1.0, end: 0.0).animate(out);
    final scale = Tween(begin: 1.0, end: 1.08).animate(out);
    // The line fades in just after the hand-off and leaves first.
    final barOut = Tween(begin: 1.0, end: 0.0).animate(CurvedAnimation(parent: _exit, curve: const Interval(0, .6)));
    return Directionality(
      textDirection: TextDirection.ltr,
      child: Stack(fit: StackFit.expand, children: [
        widget.child,
        IgnorePointer(
          child: AnnotatedRegion<SystemUiOverlayStyle>(
            value: SystemUiOverlayStyle.light,
            child: Stack(key: const Key('splashReveal'), fit: StackFit.expand, children: [
              FadeTransition(opacity: fade, child: const ColoredBox(color: Aura.ink)),
              Center(
                child: FadeTransition(
                  opacity: fade,
                  child: ScaleTransition(
                    scale: scale,
                    child: const Image(
                        image: SplashReveal.logo, width: SplashReveal._logoSize, height: SplashReveal._logoSize),
                  ),
                ),
              ),
              // The loading line under the mark.
              Align(
                alignment: Alignment.center,
                child: Transform.translate(
                  offset: const Offset(0, SplashReveal._barGap),
                  child: FadeTransition(
                    opacity: barOut,
                    child: TweenAnimationBuilder<double>(
                      tween: Tween(begin: 0, end: 1),
                      duration: const Duration(milliseconds: 160),
                      builder: (_, v, child) => Opacity(opacity: v, child: child),
                      child: Semantics(
                        key: const Key('splashLoading'),
                        label: t('טוען נתונים'),
                        child: RepaintBoundary(
                          child: SizedBox(
                            width: SplashReveal._barWidth,
                            height: 3,
                            child: CustomPaint(painter: SweepPainter(_sweep, rtl: L10n.lang.rtl)),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
              // "AURA GYM", where the native splash draws it (32 dp from the bottom, 200 x 50 dp).
              Positioned(
                left: 0,
                right: 0,
                bottom: 32,
                child: FadeTransition(
                  opacity: fade,
                  child: const Center(
                    child: Image(image: SplashReveal.branding, width: 200, height: 50),
                  ),
                ),
              ),
            ]),
          ),
        ),
      ]),
    );
  }
}
